void main() {
  vec2 uv = vTextureCoord;
  vec4 bg = texture(uTexture, uv);

  // Screen space aspect correction & anchor
  vec2 p = (uv - uPos);
  p.x *= uResolution.x / uResolution.y;

  // Camera Setup angled to view planar depth
  float yaw = (uCameraOrbit.x - 0.5) * 1.5;
  float pitch = (uCameraOrbit.y - 0.5) * 1.2 - 0.22;

  float cy = cos(yaw);
  float sy = sin(yaw);
  float cp = cos(pitch);
  float sp = sin(pitch);

  mat3 camRot = mat3(
    cy,  sy * sp,  sy * cp,
    0.0, cp,      -sp,
   -sy,  cy * sp,  cy * cp
  );

  vec3 ro = camRot * vec3(0.0, 0.65, -1.8);
  vec3 rd = normalize(camRot * vec3(p.x, p.y - 0.1, 1.35));

  // Mouse ray for interactive node bloom modulation
  vec2 mouseP = (uMousePos - uPos);
  mouseP.x *= uResolution.x / uResolution.y;
  vec3 mouseRd = normalize(camRot * vec3(mouseP.x, mouseP.y - 0.1, 1.35));

  // Stepped geometric parameters along flat plane
  float totalWidth = mix(2.6, 5.2, uLineRadius);
  float yPlane = 0.0;

  float z0 = 0.0;
  float baseZ1 = mix(1.5, 4.0, uStepDepth1);
  float baseZ2 = baseZ1 + mix(1.6, 4.2, uStepDepth2);
  float baseZ3 = baseZ2 + 4.5;

  float time = uTime * 0.025;
  float travelSpeed = mix(0.12, 0.45, uNodeSpeed);

  vec3 accumColor = vec3(0.0);
  float totalAlpha = 0.0;

  // 16 flat planar lines with staggered 90-degree bend depths
  for (int i = 0; i < 16; i++) {
    float normIdx = (float(i) - 7.5) / 7.5;
    float absNorm = abs(normIdx);
    float x0 = normIdx * (totalWidth * 0.5);
    float x1 = x0 * 0.58;
    float x2 = x0 * 0.22;

    // Stagger step depths per line so turns do not overlap
    float z1 = baseZ1 + (absNorm * 1.5 - 0.75) * uBendStagger * 1.8;
    float z2 = max(z1 + 0.6, baseZ2 + (absNorm * 1.8 - 0.9) * uBendStagger * 1.8);
    float z3 = max(z2 + 1.2, baseZ3);

    // Segment lengths for this line
    float l0 = z1 - z0;
    float l1 = abs(x0 - x1);
    float l2 = z2 - z1;
    float l3 = abs(x1 - x2);
    float l4 = length(vec2(x2, z3 - z2));
    float totalL = l0 + l1 + l2 + l3 + l4;

    // 5 Key Vertices defining the stepped 90-degree planar path
    vec3 v0 = vec3(x0, yPlane, z0);
    vec3 v1 = vec3(x0, yPlane, z1); // 1st 90-deg turn in along X
    vec3 v2 = vec3(x1, yPlane, z1); // 1st 90-deg turn along Z
    vec3 v3 = vec3(x1, yPlane, z2); // 2nd 90-deg turn in along X
    vec3 v4 = vec3(x2, yPlane, z2); // 2nd 90-deg turn along Z to center
    vec3 v5 = vec3(0.0, yPlane, z3); // Final convergence point

    // Evaluate line segments
    float sT, rT;
    float d0 = distRayToSegment(ro, rd, v0, v1, sT, rT);
    float d1 = distRayToSegment(ro, rd, v1, v2, sT, rT);
    float d2 = distRayToSegment(ro, rd, v2, v3, sT, rT);
    float d3 = distRayToSegment(ro, rd, v3, v4, sT, rT);
    float d4 = distRayToSegment(ro, rd, v4, v5, sT, rT);

    float minLineDist = min(min(min(d0, d1), min(d2, d3)), d4);

    // Core line profile and soft glow
    float depthAtten = 1.0 / (1.0 + rT * 0.12);
    float lineCore = smoothstep(0.012 * depthAtten, 0.001, minLineDist);
    float lineGlow = 0.0006 / (minLineDist * minLineDist + 0.00015) * depthAtten;

    vec3 segmentGlow = uLineColor * (lineCore * 1.5 + lineGlow * 0.85);
    accumColor += segmentGlow * 0.18;
    totalAlpha += lineCore * 0.25;

    // Traveling Node on this line with randomized phase offset per line
    float randStagger = fract(sin(float(i + 1) * 78.233 + 12.9898) * 43758.5453);
    float stagger = mix(float(i) * 0.0625, randStagger, uRandomOffset);
    float nodeProgress = fract(time * travelSpeed + stagger);

    // Compute 3D node position along stepped path
    vec3 nodePos = getNodePos(nodeProgress, x0, x1, x2, yPlane, z0, z1, z2, z3, l0, l1, l2, l3, l4, totalL);

    float nodeRayT;
    float nodeDist = distRayToPoint(ro, rd, nodePos, nodeRayT);

    // Depth attenuation & fade at entrance/exit
    float nodeZAtten = 1.0 / (1.0 + nodeRayT * 0.1);
    float lifeFade = smoothstep(0.0, 0.08, nodeProgress) * smoothstep(1.0, 0.85, nodeProgress);

    // Mouse proximity bloom boost
    float mouseRayT;
    float mouseNodeDist = distRayToPoint(ro, mouseRd, nodePos, mouseRayT);
    float mouseBloomBoost = 1.0 + uTrackMouse * (2.2 / (1.0 + mouseNodeDist * mouseNodeDist * 4.5));

    // Multi-tier Radiance Cascades
    float radMul = mix(0.5, 2.5, uRadianceIntensity) * lifeFade * nodeZAtten * mouseBloomBoost;

    // Cascade Tier 0: Intense Core
    float c0 = 0.00018 / (nodeDist * nodeDist + 0.00004) * radMul;
    // Cascade Tier 1: Inner Radiance Ring / Halo
    float c1 = 0.0012 / (nodeDist * sqrt(nodeDist) + 0.0018) * radMul;
    // Cascade Tier 2: Outer Dispersion
    float c2 = 0.004 / (nodeDist + 0.035) * radMul;

    // Radiance color graduation: core turns whiter, cascade spreads saturated node color
    vec3 nodeRadiance = mix(uNodeColor, vec3(1.0), clamp(c0 * 0.5, 0.0, 0.9)) * c0
                      + uNodeColor * c1 * 0.8
                      + mix(uNodeColor, uLineColor, 0.35) * c2 * 0.45;

    accumColor += nodeRadiance;
    totalAlpha += clamp(c0 * 0.4 + c1 * 0.2, 0.0, 1.0);

    // Subtle trail behind node
    float trailDist1 = fract(nodeProgress - 0.04);
    vec3 trailPos = getNodePos(trailDist1, x0, x1, x2, yPlane, z0, z1, z2, z3, l0, l1, l2, l3, l4, totalL);
    float trailD = distRayToPoint(ro, rd, trailPos, nodeRayT);
    accumColor += uNodeColor * (0.0004 / (trailD * trailD + 0.001)) * radMul * 0.35;
  }

  // Deep convergence vanishing point glow
  vec3 endPt = vec3(0.0, yPlane, baseZ3);
  float endRayT;
  float endDist = distRayToPoint(ro, rd, endPt, endRayT);
  accumColor += mix(uLineColor, uNodeColor, 0.5) * (0.002 / (endDist * endDist + 0.01)) * (1.0 / (1.0 + endRayT * 0.05));

  // Tone mapping and dynamic range compression
  vec3 mapped = vec3(1.0) - exp(-accumColor * 1.3);

  // Final alpha computation
  float alpha = clamp(totalAlpha + length(mapped) * 0.7, 0.0, 1.0);

  // Blend with incoming background
  vec3 finalRgb = mapped;
  if (uBlendMode > 0) {
    finalRgb = blend(uBlendMode, bg.rgb, mapped);
  }

  fragColor = vec4(mix(bg.rgb, finalRgb, alpha), max(bg.a, alpha));
}

